const url = String($input.first().json.url || '').trim();
if (!url) {
  return [{ json: { url: '', id: '', no_url: true } }];
}
const b64 = typeof Buffer !== 'undefined'
  ? Buffer.from(url).toString('base64')
  : btoa(unescape(encodeURIComponent(url)));
const id = b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { url, id, no_url: false } }];

const prep = $('Code in JavaScript').first().json;
if (prep.error) return [{ json: { url: '', found: false, verdict: 'unknown', note: 'No URL was received. Do not claim the URL was checked.' } }];
const res = $input.first().json;
const code = res.statusCode;
if (code === 404) return [{ json: { url: prep.url, found: false, verdict: 'unknown', note: 'VirusTotal has no report for this URL. It was not scanned. Do not claim a scan result.' } }];
if (code !== 200 || !res.body || !res.body.data) return [{ json: { url: prep.url, found: false, verdict: 'unknown', note: `VirusTotal lookup failed (HTTP ${code}). Treat reputation as unknown.` } }];
const a = res.body.data.attributes || {};
const s = a.last_analysis_stats || {};
const m = s.malicious || 0, su = s.suspicious || 0, h = s.harmless || 0, u = s.undetected || 0;
let verdict = 'clean';
if (m >= 3) verdict = 'malicious'; else if (m >= 1 || su >= 2) verdict = 'suspicious';
const flagged = Object.entries(a.last_analysis_results || {}).filter(([, r]) => r.category === 'malicious').map(([n, r]) => `${n}: ${r.result}`).slice(0, 5);
return [{ json: { url: prep.url, found: true, verdict, malicious: m, suspicious: su, harmless: h, undetected: u, total_engines: m + su + h + u + (s.timeout || 0), reputation: a.reputation ?? null, last_analysis_date: a.last_analysis_date ? new Date(a.last_analysis_date * 1000).toISOString() : null, flagged_by: flagged } }];
